import * as Core from '../../Core';
import * as Views from '../.';
class CartUse {
    _id;
    _cart;
    constructor(id, cart) {
        this._id = id;
        this._cart = cart;
    }
    html() {
        let html = document.createElement('div');
        html.className = 'cart';
        html.draggable = true;
        let title = document.createElement('div');
        title.className = 'cart__title';
        title.innerHTML = this._cart.title();
        let description = document.createElement('div');
        description.className = 'cart__description';
        description.innerHTML = this._cart.description();
        let type = document.createElement('div');
        type.className = 'cart__type';
        type.innerHTML = this._cart.getType();
        let btnDetails = document.createElement('button');
        btnDetails.className = 'cart__details';
        btnDetails.innerHTML = 'details';
        btnDetails.addEventListener('click', () => {
            let popup = new Views.PopUp(this._cart.title(), this._cart.description());
            popup.show();
        });
        let btnDel = document.createElement('button');
        btnDel.className = 'cart__use';
        btnDel.innerHTML = 'del';
        btnDel.addEventListener('click', () => this.del());
        html.append(title);
        html.append(description);
        html.append(type);
        html.append(btnDetails);
        html.append(btnDel);
        return html;
    }
    use() {
        this._cart.use(this._id);
    }
    del() {
        if (this._cart.getType() === Core.CartType.Action) {
            this._cart.delAction();
        }
        if (this._cart.getType() === Core.CartType.Improve) {
            this._cart.delImprove(this._id);
        }
    }
    action() {
        try {
            this._cart.action();
        }
        catch (e) {
            let popup = new Views.PopUp('Нельзя использовать карту', e.message);
            popup.show();
        }
    }
}
export default CartUse;
